package com.mediassistrover.backend.service.impl;

import com.fasterxml.jackson.databind.*;
import com.mediassistrover.backend.dto.pi.request.*;
import com.mediassistrover.backend.dto.pi.request.JobRuntimePayloads.*;
import com.mediassistrover.backend.dto.pi.response.PiResponses.*;
import com.mediassistrover.backend.entity.*;
import com.mediassistrover.backend.enums.*;
import com.mediassistrover.backend.exception.*;
import com.mediassistrover.backend.repository.*;
import com.mediassistrover.backend.security.*;
import com.mediassistrover.backend.service.JobStepInputResolver;
import com.mediassistrover.backend.service.JobStepRuntimeGuard;
import com.mediassistrover.backend.service.PiJobRuntimeService;
import com.mediassistrover.backend.service.WorkflowRuntimeTransitionService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import org.springframework.security.access.AccessDeniedException;
import com.mediassistrover.backend.validation.RuntimeAuthorizationPolicy;
import java.util.*;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PiJobRuntimeServiceImpl implements PiJobRuntimeService {
    private final JobRepository jobRepository; private final JobTaskRepository taskRepository;
    private final JobStepRepository stepRepository; private final JobEventRepository eventRepository;
    private final RobotRepository robotRepository; private final ObjectMapper objectMapper; private final Clock clock;
    private final JobStepInputResolver inputResolver;
    private final WorkflowRuntimeTransitionService transitionService;
    private final JobStepRuntimeGuard runtimeGuard;
    private final com.mediassistrover.backend.validation.StepResultContractValidator stepResultValidator;
    @Override public Optional<JobCommandResponse> nextCommand(DevicePrincipal p){Robot robot=robot(p.robotId());List<Job> active=jobRepository.findByRobotRobotIdAndStatusIn(p.robotId(),List.of(JobStatus.QUEUED,JobStatus.ACCEPTED,JobStatus.RUNNING));Job cancel=active.stream().filter(j->j.getCancelCommandId()!=null).min(Comparator.comparing(Job::getCancelRequestedAt)).orElse(null);if(cancel!=null)return Optional.of(command(cancel,"CANCEL",cancel.getCancelCommandId()));Job dispatch=active.stream().filter(j->j.getStatus()==JobStatus.QUEUED&&j.getDispatchCommandId()!=null).min(Comparator.comparing(Job::getQueuedAt)).orElse(null);return Optional.ofNullable(dispatch).map(j->command(j,"DISPATCH",j.getDispatchCommandId()));}
    @Override @Transactional public AckResponse commandAck(UUID commandId,PiEnvelope<CommandAckPayload> e,DevicePrincipal p){Job j=validateJobEnvelope(e,p,"COMMAND_ACK");if(duplicate(e))return ack(e,robot(p.robotId()),true,null);Instant now=Instant.now(clock);String previous=j.getStatus().name();if(commandId.equals(j.getCancelCommandId())){if(e.payload().accepted()){if(hasPhysicalImpact(j))recovery(j,"CANCEL_AFTER_PHYSICAL_ACTION","Cancellation acknowledged after an unlock or payload operation; reconciliation is required");else{j.setStatus(JobStatus.CANCELLED);j.setEndedAt(now);completeRequest(j,ServiceRequestStatus.CANCELLED,now);releaseRobot(j);}}else recovery(j,"CANCEL_REJECTED",e.payload().reason());}else if(commandId.equals(j.getDispatchCommandId())){if(j.getStatus()!=JobStatus.QUEUED)throw new BusinessRuleException("DISPATCH ACK is not valid in "+j.getStatus());if(e.payload().accepted()){j.setStatus(JobStatus.ACCEPTED);j.setAcceptedAt(now);if(j.getRobot().getStatus()==RobotStatus.IDLE)j.getRobot().setStatus(RobotStatus.BUSY);}else {j.setStatus(JobStatus.FAILED);j.setEndedAt(now);j.setErrorCode("DISPATCH_REJECTED");j.setFailureReason(e.payload().reason());completeRequest(j,ServiceRequestStatus.FAILED,now);}}else throw new BusinessRuleException("Command does not belong to Job");saveEvent(e,j,null,"COMMAND_ACK",previous,j.getStatus().name(),objectMapper.valueToTree(e.payload()));return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse jobStarted(UUID id,PiEnvelope<JobStartedPayload> e,DevicePrincipal p){Job j=validateJobEnvelope(id,e,p,"JOB_STARTED");if(duplicate(e))return ack(e,j.getRobot(),true,null);if(j.getStatus()!=JobStatus.ACCEPTED)throw new BusinessRuleException("Job can start only after DISPATCH ACK");String old=j.getStatus().name();j.setStatus(JobStatus.RUNNING);j.setStartedAt(Instant.now(clock));if(e.payload().runtimeContext()!=null)j.setContextJson(e.payload().runtimeContext());if(j.getServiceRequest()!=null)j.getServiceRequest().setStatus(ServiceRequestStatus.IN_PROGRESS);saveEvent(e,j,null,"JOB_STARTED",old,j.getStatus().name(),objectMapper.valueToTree(e.payload()));return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse jobResult(UUID id,PiEnvelope<JobResultPayload> e,DevicePrincipal p){Job j=validateJobEnvelope(id,e,p,"JOB_RESULT");if(duplicate(e))return ack(e,j.getRobot(),true,null);if(j.getStatus()!=JobStatus.RUNNING)throw new BusinessRuleException("Job result requires RUNNING status");runtimeGuard.requireSuccessfulTerminal(j);Instant now=Instant.now(clock);j.setStatus(JobStatus.SUCCEEDED);j.setResultJson(e.payload().result());j.setEndedAt(now);finalizeTasks(j,now);completeRequest(j,ServiceRequestStatus.COMPLETED,now);releaseRobot(j);saveEvent(e,j,null,"JOB_SUCCEEDED",JobStatus.RUNNING.name(),JobStatus.SUCCEEDED.name(),e.payload().result());return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse jobError(UUID id,PiEnvelope<JobErrorPayload> e,DevicePrincipal p){Job j=validateJobEnvelope(id,e,p,"JOB_ERROR");if(duplicate(e))return ack(e,j.getRobot(),true,null);if(j.getStatus()!=JobStatus.ACCEPTED&&j.getStatus()!=JobStatus.RUNNING)throw new BusinessRuleException("Job error is not valid in "+j.getStatus());String old=j.getStatus().name();Instant now=Instant.now(clock);if(hasPhysicalImpact(j))recovery(j,"ERROR_AFTER_PHYSICAL_ACTION",e.payload().failureReason());else{j.setStatus(JobStatus.FAILED);j.setErrorCode(e.payload().errorCode());j.setFailureReason(e.payload().failureReason());j.setEndedAt(now);completeRequest(j,ServiceRequestStatus.FAILED,now);releaseRobot(j);}saveEvent(e,j,null,j.getStatus()==JobStatus.RECOVERY_REQUIRED?"JOB_RECOVERY_REQUIRED":"JOB_FAILED",old,j.getStatus().name(),objectMapper.valueToTree(e.payload()));return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse stepStarted(UUID id,PiEnvelope<StepStartedPayload> e,DevicePrincipal p){JobStep s=validateStepEnvelope(id,e,p,"STEP_STARTED");if(duplicate(e))return ack(e,s.getJobTask().getJob().getRobot(),true,null);if(s.getStatus()!=JobStepStatus.PENDING&&s.getStatus()!=JobStepStatus.RETRYING)throw new BusinessRuleException("Step cannot start in "+s.getStatus());if(s.getStep().getStepType().getExecutorKind()==StepExecutorKind.SERVER)throw new BusinessRuleException("SERVER Step must start through /step-services/execute");Job j=s.getJobTask().getJob();if(j.getStatus()!=JobStatus.RUNNING)throw new BusinessRuleException("Job is not RUNNING");String old=s.getStatus().name();if(s.getStatus()==JobStepStatus.PENDING){runtimeGuard.requireStartAllowed(s);s.setResolvedInputsJson(inputResolver.resolve(s));}s.setStatus(JobStepStatus.RUNNING);s.setAttemptNo(e.payload().attemptNo());s.setStartedAt(Instant.now(clock));JobTask task=s.getJobTask();if(task.getStatus()==JobTaskStatus.PENDING){task.setStatus(JobTaskStatus.RUNNING);task.setStartedAt(Instant.now(clock));}saveEvent(e,j,s,"STEP_STARTED",old,s.getStatus().name(),objectMapper.valueToTree(e.payload()));return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse stepResult(UUID id,PiEnvelope<StepResultPayload> e,DevicePrincipal p){JobStep s=validateStepEnvelope(id,e,p,"STEP_RESULT");RuntimeAuthorizationPolicy.requireDeviceCallback(s);if(duplicate(e))return ack(e,s.getJobTask().getJob().getRobot(),true,null);RuntimeAuthorizationPolicy.requireRunning(s.getJobTask().getJob());if(s.getStatus()!=JobStepStatus.RUNNING)throw new BusinessRuleException("Step result requires RUNNING status");stepResultValidator.validate(s,e.payload().result());s.setStatus(JobStepStatus.SUCCEEDED);s.setResultJson(e.payload().result());s.setEndedAt(Instant.now(clock));updateTaskIfComplete(s.getJobTask());Job j=s.getJobTask().getJob();saveEvent(e,j,s,"STEP_SUCCEEDED",JobStepStatus.RUNNING.name(),JobStepStatus.SUCCEEDED.name(),e.payload().result());return ack(e,j.getRobot(),false,null);}
    @Override @Transactional public AckResponse stepError(UUID id,PiEnvelope<StepErrorPayload> e,DevicePrincipal p){JobStep s=validateStepEnvelope(id,e,p,"STEP_ERROR");RuntimeAuthorizationPolicy.requireDeviceCallback(s);if(duplicate(e))return ack(e,s.getJobTask().getJob().getRobot(),true,null);RuntimeAuthorizationPolicy.requireRunning(s.getJobTask().getJob());if(s.getStatus()!=JobStepStatus.RUNNING)throw new BusinessRuleException("Step error requires RUNNING status");Step definition=s.getStep();JobStepStatus next=e.payload().retryable()&&s.getAttemptNo()<definition.getMaxAttempts()?JobStepStatus.RETRYING:JobStepStatus.FAILED;s.setStatus(next);s.setErrorCode(e.payload().errorCode());s.setErrorDetailsJson(e.payload().details());if(next==JobStepStatus.FAILED)s.setEndedAt(Instant.now(clock));Job j=s.getJobTask().getJob();if(next==JobStepStatus.FAILED&&hasPhysicalImpact(j))recovery(j,"STEP_ERROR_AFTER_PHYSICAL_ACTION",e.payload().errorCode());saveEvent(e,j,s,"STEP_ERROR",JobStepStatus.RUNNING.name(),next.name(),objectMapper.valueToTree(e.payload()));return ack(e,j.getRobot(),false,null);}

    @Override @Transactional
    public JobStepCommand createStepVisit(UUID jobId,UUID stepId,PiEnvelope<CreateStepVisitPayload> e,DevicePrincipal p){
        validate(e,p,"STEP_VISIT_CREATE");
        if(!jobId.equals(e.jobId()))throw new BusinessRuleException("Path jobId does not match envelope");
        Job j=job(jobId);if(j.getRobot()==null||!j.getRobot().getRobotId().equals(p.robotId()))throw new AccessDeniedException("Job is not assigned to this robot");
        Optional<JobStep> existing=stepRepository.findByOperationKey(e.operationKey());
        if(existing.isPresent()){
            JobStep found=existing.get();
            Job foundJob=found.getJobTask().getJob();
            if(!foundJob.getJobId().equals(jobId)||foundJob.getRobot()==null||!foundJob.getRobot().getRobotId().equals(p.robotId()))
                throw new AccessDeniedException("operationKey is outside this Job/Robot scope");
            if(!found.getStep().getStepId().equals(stepId))throw new ConflictException("operationKey already identifies another Step");
            return stepCommand(found);
        }
        RuntimeAuthorizationPolicy.requireRunning(j);
        if(duplicate(e))throw new ConflictException("Duplicate visit message does not identify an existing JobStep");
        JobStep previous=stepRepository.findById(e.payload().previousJobStepId()).orElseThrow(()->new ResourceNotFoundException("Previous JobStep not found"));
        if(!previous.getJobTask().getJob().getJobId().equals(jobId))throw new BusinessRuleException("Previous JobStep does not belong to Job");
        StepTransition route=transitionService.resolve(previous);
        if(route.getToStep()==null)throw new BusinessRuleException("Previous Step resolves to terminal status "+route.getTerminalStatus());
        if(!route.getToStep().getStepId().equals(stepId))throw new BusinessRuleException("Requested Step is not the selected transition target");
        if(stepRepository.findByJobId(jobId).stream().anyMatch(s->s.getStep().getStepId().equals(stepId)&&(s.getStatus()==JobStepStatus.PENDING||s.getStatus()==JobStepStatus.RUNNING||s.getStatus()==JobStepStatus.RETRYING)))throw new BusinessRuleException("An executable visit for the target Step already exists");
        long visits=stepRepository.countByJobTaskJobJobIdAndStepStepId(jobId,stepId);
        if(visits>=route.getToStep().getMaxVisits())throw new BusinessRuleException("Step maxVisits exceeded");
        if(stepRepository.countByJobTaskJobJobId(jobId)>=j.getWorkflow().getMaxTotalVisits())throw new BusinessRuleException("Workflow maxTotalVisits exceeded");
        JobTask task=taskRepository.findByJobJobIdOrderBySequenceNoAsc(jobId).stream().filter(t->t.getTask().getTaskId().equals(route.getToStep().getTask().getTaskId())).findFirst().orElseThrow();
        long sequence=stepRepository.findByJobId(jobId).stream().mapToLong(JobStep::getExecutionSequenceNo).max().orElse(0)+1;
        JobStep created=stepRepository.save(JobStep.builder().jobTask(task).step(route.getToStep()).visitNo((int)visits+1).executionSequenceNo(sequence).stepCodeSnapshot(route.getToStep().getStepCode()).stepTypeSnapshot(route.getToStep().getStepType().name()).resolvedInputsJson(objectMapper.createObjectNode()).status(JobStepStatus.PENDING).attemptNo(1).operationKey(e.operationKey()).timeoutSecSnapshot(route.getToStep().getTimeoutSec()).build());
        saveEvent(e,j,created,"JOB_STEP_VISIT_CREATED",null,JobStepStatus.PENDING.name(),objectMapper.valueToTree(e.payload()));
        return stepCommand(created);
    }

    private JobCommandResponse command(Job j,String type,UUID id){List<JobStepCommand> steps=type.equals("DISPATCH")?stepRepository.findByJobId(j.getJobId()).stream().map(this::stepCommand).toList():List.of();return new JobCommandResponse("1.0",id,type,UUID.randomUUID(),j.getRobot().getRobotId(),j.getJobId(),j.getWorkflowHash(),j.getSchemaVersion(),j.getGraphVersion(),type.equals("DISPATCH")?j.getDispatchExpiresAt():null,type.equals("DISPATCH")?j.getWorkflow().getCompiledDefinitionJson():null,type.equals("DISPATCH")?j.getInputJson():null,type.equals("DISPATCH")?j.getContextJson():null,steps);}
    private JobStepCommand stepCommand(JobStep s){return new JobStepCommand(s.getJobStepId(),s.getStep().getStepId(),s.getStepCodeSnapshot(),s.getVisitNo(),s.getOperationKey(),s.getStatus());}
    private Job validateJobEnvelope(PiEnvelope<?> e,DevicePrincipal p,String type){if(e.jobId()==null)throw new BusinessRuleException("jobId is required");return validateJobEnvelope(e.jobId(),e,p,type);}
    private Job validateJobEnvelope(UUID id,PiEnvelope<?> e,DevicePrincipal p,String type){validate(e,p,type);if(!id.equals(e.jobId()))throw new BusinessRuleException("Path jobId does not match envelope");Job j=job(id);if(j.getRobot()==null||!j.getRobot().getRobotId().equals(p.robotId()))throw new AccessDeniedException("Job is not assigned to this robot");return j;}
    private JobStep validateStepEnvelope(UUID id,PiEnvelope<?> e,DevicePrincipal p,String type){validate(e,p,type);if(e.jobId()==null)throw new BusinessRuleException("jobId is required");job(e.jobId());if(!id.equals(e.jobStepId()))throw new BusinessRuleException("Path jobStepId does not match envelope");JobStep s=stepRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("JobStep not found: "+id));Job j=s.getJobTask().getJob();if(e.jobId()==null||!e.jobId().equals(j.getJobId())||j.getRobot()==null||!j.getRobot().getRobotId().equals(p.robotId()))throw new AccessDeniedException("JobStep does not belong to envelope Job/Robot");if(!e.operationKey().equals(s.getOperationKey()))throw new BusinessRuleException("operationKey does not match JobStep");return s;}
    private void validate(PiEnvelope<?> e,DevicePrincipal p,String type){if(!"1.0".equals(e.protocolVersion()))throw new BusinessRuleException("Unsupported protocolVersion");if(!p.robotId().equals(e.robotId()))throw new AccessDeniedException("Envelope robotId does not match device token");if(!type.equals(e.messageType()))throw new BusinessRuleException("Unexpected messageType; expected "+type);if(e.occurredAt().isAfter(Instant.now(clock).plusSeconds(300)))throw new BusinessRuleException("occurredAt is too far in the future");}
    private boolean duplicate(PiEnvelope<?> e){return eventRepository.existsById(e.messageId())||eventRepository.existsByProducerSessionIdAndSequenceNo(e.producerSessionId(),e.sequenceNo());}
    private void saveEvent(PiEnvelope<?> e,Job j,JobStep s,String type,String old,String next,JsonNode data){Instant now=Instant.now(clock);eventRepository.save(JobEvent.builder().jobEventId(e.messageId()).job(j).robot(j.getRobot()).jobTask(s==null?null:s.getJobTask()).jobStep(s).producerType(JobEventProducerType.ROBOT).producerSessionId(e.producerSessionId()).sequenceNo(e.sequenceNo()).eventType(type).correlationKey(e.correlationId().toString()).attemptNo(s==null?null:s.getAttemptNo()).previousStatus(old).newStatus(next).statusScope(s==null?"JOB":"JOB_STEP").eventDataJson(data==null?objectMapper.createObjectNode():data).occurredAt(e.occurredAt()).receivedAt(now).persistedAt(now).build());}
    private void updateTaskIfComplete(JobTask task){List<JobStep> steps=stepRepository.findByJobId(task.getJob().getJobId()).stream().filter(s->s.getJobTask().getJobTaskId().equals(task.getJobTaskId())).toList();if(steps.stream().allMatch(s->s.getStatus()==JobStepStatus.SUCCEEDED)){task.setStatus(JobTaskStatus.SUCCEEDED);task.setEndedAt(Instant.now(clock));}}
    private void finalizeTasks(Job j,Instant now){for(JobTask task:taskRepository.findByJobJobIdOrderBySequenceNoAsc(j.getJobId())){List<JobStep> steps=stepRepository.findByJobId(j.getJobId()).stream().filter(s->s.getJobTask().getJobTaskId().equals(task.getJobTaskId())).toList();boolean succeeded=steps.stream().anyMatch(s->s.getStatus()==JobStepStatus.SUCCEEDED);boolean failed=steps.stream().anyMatch(s->s.getStatus()==JobStepStatus.FAILED||s.getStatus()==JobStepStatus.TIMED_OUT);task.setStatus(succeeded?JobTaskStatus.SUCCEEDED:failed?JobTaskStatus.FAILED:JobTaskStatus.NOT_VISITED);task.setEndedAt(now);}}
    private void completeRequest(Job j,ServiceRequestStatus status,Instant now){if(j.getServiceRequest()!=null){j.getServiceRequest().setStatus(status);if(status==ServiceRequestStatus.CANCELLED)j.getServiceRequest().setCancelledAt(now);else j.getServiceRequest().setCompletedAt(now);}}
    private void releaseRobot(Job j){if(j.getRobot()!=null&&j.getRobot().getStatus()==RobotStatus.BUSY)j.getRobot().setStatus(RobotStatus.IDLE);}
    private void recovery(Job j,String code,String reason){j.setStatus(JobStatus.RECOVERY_REQUIRED);j.setErrorCode(code);j.setFailureReason(reason);if(j.getServiceRequest()!=null)j.getServiceRequest().setStatus(ServiceRequestStatus.RECOVERY_REQUIRED);if(j.getRobot()!=null)j.getRobot().setStatus(RobotStatus.ERROR);}
    private boolean hasPhysicalImpact(Job j){return stepRepository.findByJobId(j.getJobId()).stream().filter(s->s.getStatus()==JobStepStatus.SUCCEEDED).anyMatch(s->StepType.HANDLE_PAYLOAD.name().equals(s.getStepTypeSnapshot())||StepType.CONTROL_HARDWARE.name().equals(s.getStepTypeSnapshot())&&s.getResultJson()!=null&&s.getResultJson().path("commanded_state").asText().startsWith("UNLOCK"));}
    private AckResponse ack(PiEnvelope<?> e,Robot robot,boolean duplicate,String reason){return new AckResponse(e.messageId(),e.operationKey(),e.correlationId(),true,duplicate,Instant.now(clock),robot.getStatus(),false,false,reason);}
    private Job job(UUID id){return jobRepository.lockById(id).orElseThrow(()->new ResourceNotFoundException("Job not found: "+id));}
    private Robot robot(UUID id){return robotRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Robot not found: "+id));}
}
